<!-- 文件作用：独立管理微信场景模板、安全字段映射、发送记录和安全重试，普通用户不可访问。 -->
<template><AppShell title="微信订阅管理" back><view v-if="error" class="error-box subscriptions-admin-error"><text>{{error}}</text><button class="text-btn" :disabled="loading||busy" @click="load">重新加载</button></view><EmptyState v-if="!authorized&&!loading&&!error" title="仅平台管理员可访问" detail="微信模板和发送记录仅供平台管理员管理。" icon="shield"/><view v-if="loading&&!settings" class="loading-line">正在读取订阅配置…</view><template v-if="authorized"><view class="subscriptions-admin-tabs"><button :class="['subscriptions-admin-tab',{active:tab==='settings'}]" @click="chooseTab('settings')">模板配置</button><button :class="['subscriptions-admin-tab',{active:tab==='deliveries'}]" @click="chooseTab('deliveries')">发送记录</button></view><template v-if="tab==='settings'&&settings"><view class="subscriptions-master"><view class="subscriptions-setting-copy"><text class="subscriptions-setting-title">启用微信提醒</text><text class="subtle-note">按用户授权发送，失败不影响交易。</text></view><NativeSwitch :checked="settings.enabled" :disabled="busy" @change="settings.enabled=$event.detail.value"/></view><view v-for="scene in settings.scenes" :key="scene.scene" class="subscriptions-scene"><button class="subscriptions-scene-heading" @click="expanded=expanded===scene.scene?'':scene.scene"><text class="subscriptions-setting-title">{{sceneLabel(scene.scene)}}</text><text class="subscriptions-setting-state">{{scene.template_id&&Object.keys(scene.fields).length?'已配置':'未配置'}}</text><Icon :name="expanded===scene.scene?'top':'arrow'" :size="14"/></button><view v-if="expanded===scene.scene" class="subscriptions-scene-body"><view class="subscriptions-inline"><text class="field-label">启用此场景</text><NativeSwitch :checked="scene.enabled" :disabled="busy" @change="scene.enabled=$event.detail.value"/></view><text class="subtle-note">{{sceneDescription(scene.scene)}}</text><view class="field"><view class="subscriptions-inline"><text class="field-label">模板ID</text><button class="text-btn subscriptions-select-template" :disabled="busy||templatesLoading" @click="openTemplates(scene.scene)">{{templatesLoading?'正在读取…':'选择微信模板'}}</button></view><input v-model="scene.template_id" class="input subscriptions-template-id" :disabled="busy" maxlength="128" placeholder="微信公众平台模板ID"/></view><text class="subtle-note">每项对应固定业务事件，仅使用含义匹配的微信模板。</text><text class="field-label subscriptions-field-heading">字段映射</text><view v-for="(field,index) in fieldRows[scene.scene]||[]" :key="index" class="subscriptions-mapping"><input v-model="field.key" class="input subscriptions-field-key" :disabled="busy" maxlength="32" placeholder="thing1"/><picker class="subscriptions-source-picker" :range="sourceOptions" range-key="label" :value="sourceOptions.findIndex(item=>item.value===field.source)" :disabled="busy" @change="field.source=sourceOptions[Number($event.detail.value)].value"><view class="input subscriptions-source-value">{{sourceLabel(field.source)}}<Icon name="bottom" :size="11"/></view></picker><button class="subscriptions-remove" :disabled="busy" aria-label="删除字段" @click="fieldRows[scene.scene]?.splice(index,1)"><Icon name="close" :size="17"/></button></view><button class="text-btn subscriptions-add-field" :disabled="busy||(fieldRows[scene.scene]?.length||0)>=10" @click="addField(scene.scene)"><Icon name="plus" :size="14"/>添加字段</button></view></view><text class="subtle-note subscriptions-admin-note">请使用当前小程序类目可用模板；字段按微信模板填写，仅映射平台允许的数据。关闭场景可保留完整配置或全部清空。</text><button class="btn subscriptions-save" :disabled="busy||loading" @click="save">{{busy?'正在保存…':'保存配置'}}</button></template><template v-else-if="tab==='deliveries'"><view class="subscriptions-delivery-tools"><text class="subtle-note">{{total}} 条记录</text><button class="text-btn" :disabled="loading||busy" @click="loadDeliveries()">刷新记录</button></view><text v-if="deliveryError" class="subscriptions-delivery-error">{{deliveryError}}</text><view v-for="item in deliveries" :key="item.id" class="subscriptions-delivery"><view class="subscriptions-inline"><text class="subscriptions-delivery-title">{{item.title}}</text><text :class="['subscriptions-delivery-status',{'subscriptions-sent':item.status==='sent'}]">{{deliveryLabel(item.status)}}</text></view><text class="subtle-note">{{sceneLabel(item.scene)}} · {{item.attempts}} 次尝试 · {{time(item.created_at)}}</text><text v-if="item.reason" class="subscriptions-delivery-reason">{{item.reason}}</text><text v-if="item.error_code" class="subtle-note">结果码 {{item.error_code}}</text><button v-if="item.can_retry" class="text-btn subscriptions-retry" :disabled="busy" @click="retry(item)">重试发送</button></view><EmptyState v-if="!loading&&!deliveries.length&&!deliveryError" title="暂无发送记录" detail="真实业务产生提醒后，发送结果会展示在这里。" icon="bell"/><button v-if="deliveries.length<total" class="text-btn subscriptions-more" :disabled="loading||busy" @click="loadDeliveries(true)">加载更多</button><text class="subtle-note subscriptions-admin-note">缺少授权、未配置模板或不确定发送结果均会如实记录；仅安全失败可重试。</text></template></template><FinancePopup :opened="templatesOpened" title="选择微信模板" :busy="templatesLoading" @close="templatesOpened=false"><text v-if="templateError" class="subscriptions-delivery-error">{{templateError}}</text><view v-if="templatesLoading" class="loading-line">正在读取当前小程序模板…</view><button v-for="item in templates" :key="item.template_id" class="subscriptions-template-option" @click="chooseTemplate(item)"><text class="subscriptions-setting-title">{{item.title}}</text><text class="subtle-note">{{item.fields.map(field=>field.label).join(' · ')}}</text><text class="subscriptions-template-code">{{item.template_id}}</text></button><text v-if="!templatesLoading&&!templates.length&&!templateError" class="subtle-note">尚无适用于此场景的一次性模板，请先在微信公众平台添加含义匹配的模板。</text><text class="subtle-note">仅显示本功能支持的模板字段；选择后仍需核对字段来源，不会自动启用。</text></FinancePopup></AppShell></template>
<script setup lang="ts">
import {computed,ref,reactive,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import EmptyState from '../../components/EmptyState.vue'
import Icon from '../../components/Icon.vue'
import NativeSwitch from '../../components/NativeSwitch.vue'
import FinancePopup from '../../components/FinancePopup.vue'
import {state,init,sessionRevision} from '../../lib/store'
import {token,errorMessage} from '../../api/client'
import {getSubscriptionSettings,saveSubscriptionSettings,listSubscriptionDeliveries,retrySubscriptionDelivery,listSubscriptionTemplates} from '../../api/subscriptions.api'
import {SUBSCRIPTION_LABELS,SUBSCRIPTION_SOURCES,validateSubscriptionSettings,subscriptionSourceForField,subscriptionTemplateAllowed,subscriptionTemplateFieldsSupported} from '../../lib/subscriptions'
import {notify,time} from '../../lib/format'
import type {SubscriptionSettings,SubscriptionSettingsBody,SubscriptionScene,SubscriptionFieldSource,SubscriptionDelivery,SubscriptionDeliveryStatus,SubscriptionWechatTemplate} from '../../types/subscriptions'
/** 字段名与来源使用独立草稿行，重复字段必须显式拦截，不能被对象覆盖。 */
interface FieldRow {key:string;source:SubscriptionFieldSource}
const settings=ref<SubscriptionSettings|null>(null),authorized=ref(false),loading=ref(false),busy=ref(false),error=ref(''),tab=ref<'settings'|'deliveries'>('settings'),expanded=ref<SubscriptionScene|''>('provider_order'),fieldRows=reactive<Partial<Record<SubscriptionScene,FieldRow[]>>>({})
const deliveries=ref<SubscriptionDelivery[]>([]),total=ref(0),deliveryError=ref(''),templatesOpened=ref(false),templatesLoading=ref(false),templates=ref<SubscriptionWechatTemplate[]>([]),templateError=ref(''),templateScene=ref<SubscriptionScene>('provider_order')
const sourceOptions=computed(()=>Object.entries(SUBSCRIPTION_SOURCES).filter(([value])=>settings.value?.sources.includes(value as SubscriptionFieldSource)).map(([value,label])=>({value:value as SubscriptionFieldSource,label})))
let visible=false,disposed=false,readVersion=0,operation=0,deliveryVersion=0,templateVersion=0
/** 捕获当前平台管理员身份，客户端角色不代替后端授权。 */
function session(){return{id:state.user?.id,token:token(),revision:sessionRevision()}}
/** 隐藏、销毁与换号后拒绝所有私密管理数据回填。 */
function same(owner:ReturnType<typeof session>){return visible&&!disposed&&state.user?.role==='admin'&&owner.id===state.user.id&&owner.token===token()&&owner.revision===sessionRevision()}
/** 显示固定中文场景名，未知场景仍不产生可编辑动态代码。 */
function sceneLabel(scene:SubscriptionScene){return SUBSCRIPTION_LABELS[scene]||scene}
/** 读取服务端固定场景说明。 */
function sceneDescription(scene:SubscriptionScene){return settings.value?.scene_catalog.find(item=>item.scene===scene)?.description||''}
/** 显示管理员可选的安全字段来源。 */
function sourceLabel(source:SubscriptionFieldSource){return SUBSCRIPTION_SOURCES[source]||'请选择来源'}
/** 按真实状态展示原因，不把排队或不确定状态标记成功。 */
function deliveryLabel(status:SubscriptionDeliveryStatus){return {pending:'待发送',preparing:'准备中',sending:'发送中',sent:'已发送',skipped_disabled:'平台已关闭',skipped_config:'模板未匹配',skipped_preference:'用户已关闭',skipped_no_authorization:'缺少本次授权',skipped_identity:'身份不可用',expired:'已过期',failed_retryable:'失败可重试',failed_final:'发送失败',uncertain:'结果不确定'}[status]||status}
/** 接收配置后建立不共享引用的字段草稿。 */
function apply(result:SubscriptionSettings){settings.value={...result,scenes:result.scenes.map(item=>({...item,fields:{...item.fields}}))};for(const key of Object.keys(fieldRows))delete fieldRows[key as SubscriptionScene];for(const item of settings.value.scenes)fieldRows[item.scene]=Object.entries(item.fields).map(([key,source])=>({key,source}))}
/** 初始化失败也显示错误和重试，不把错误藏进未核实角色分支。 */
async function load(){if(!visible)return;const version=++readVersion;loading.value=true;error.value='';try{await init();if(!visible||version!==readVersion)return;authorized.value=state.user?.role==='admin';if(!authorized.value){settings.value=null;return}const owner=session(),result=await getSubscriptionSettings();if(version===readVersion&&same(owner))apply(result)}catch(err){if(visible&&version===readVersion)error.value=errorMessage(err)}finally{if(version===readVersion)loading.value=false}}
/** 添加一个空字段草稿，不预填会误发的默认映射。 */
function addField(scene:SubscriptionScene){if(busy.value)return;const rows=fieldRows[scene]||(fieldRows[scene]=[]);if(rows.length<10)rows.push({key:'',source:'title'})}
/** 组装约定的可写字段并阻止空名、重复名和无来源映射。 */
function body():SubscriptionSettingsBody{if(!settings.value)throw new Error('请先读取配置');const value={enabled:settings.value.enabled,scenes:settings.value.scenes.map(item=>{const fields:Record<string,SubscriptionFieldSource>={};for(const row of fieldRows[item.scene]||[]){const key=row.key.trim();if(Object.hasOwn(fields,key))throw new Error('同一模板不能使用重复字段名');fields[key]=row.source}return{scene:item.scene,enabled:item.enabled,template_id:item.template_id.trim(),fields}})};validateSubscriptionSettings(value);return value}
/** 保存不携带目录或任意微信秘密，旧账号返回不能覆盖新草稿。 */
async function save(){if(busy.value||!authorized.value||!same(session()))return;const owner=session(),version=++operation;busy.value=true;error.value='';try{const result=await saveSubscriptionSettings(body());if(same(owner)&&version===operation){apply(result);notify('订阅消息配置已保存')}}catch(err){if(same(owner)&&version===operation)error.value=errorMessage(err)}finally{if(version===operation)busy.value=false}}
/** 切页签只读取需要的数据，保留当前配置草稿直到离开。 */
function chooseTab(value:'settings'|'deliveries'){if(busy.value||tab.value===value)return;tab.value=value;if(value==='deliveries')void loadDeliveries()}
/** 服务端分页和状态不作客户端假重试推导。 */
async function loadDeliveries(more=false){if(!authorized.value||!same(session())||busy.value||more&&loading.value)return;const owner=session(),version=++deliveryVersion;loading.value=true;deliveryError.value='';try{const result=await listSubscriptionDeliveries({offset:more?deliveries.value.length:0,limit:20});if(same(owner)&&version===deliveryVersion){deliveries.value=more?[...deliveries.value,...result.items.filter(item=>!deliveries.value.some(old=>old.id===item.id))]:result.items;total.value=result.total}}catch(err){if(same(owner)&&version===deliveryVersion)deliveryError.value=errorMessage(err)}finally{if(version===deliveryVersion)loading.value=false}}
/** 仅 can_retry 记录可重试，最终资格再次由服务端核验。 */
async function retry(item:SubscriptionDelivery){if(busy.value||!item.can_retry||!same(session()))return;const owner=session(),version=++operation;busy.value=true;deliveryError.value='';try{await retrySubscriptionDelivery(item.id);if(same(owner)&&version===operation)notify('已提交安全重试')}catch(err){if(same(owner)&&version===operation)deliveryError.value=errorMessage(err)}finally{if(version===operation){busy.value=false;if(same(owner))void loadDeliveries()}}}
/** 从当前微信账号读取真实模板，不使用演示模板伪装配置。 */
async function openTemplates(scene:SubscriptionScene){if(busy.value||templatesLoading.value||!same(session()))return;templateScene.value=scene;templatesOpened.value=true;templateError.value='';const owner=session(),version=++templateVersion;templatesLoading.value=true;try{const result=await listSubscriptionTemplates();if(same(owner)&&version===templateVersion)templates.value=result.items.filter(item=>Number(item.type)===2&&subscriptionTemplateAllowed(scene,item.title)&&subscriptionTemplateFieldsSupported(item.fields))}catch(err){if(same(owner)&&version===templateVersion)templateError.value=errorMessage(err)}finally{if(version===templateVersion)templatesLoading.value=false}}
/** 选择模板只生成待核对草稿，不自动启用、不自动绑定业务事件。 */
function chooseTemplate(template:SubscriptionWechatTemplate){const scene=settings.value?.scenes.find(item=>item.scene===templateScene.value);if(!scene||busy.value||!same(session())||Number(template.type)!==2||!subscriptionTemplateAllowed(scene.scene,template.title)||!subscriptionTemplateFieldsSupported(template.fields))return;scene.template_id=template.template_id;scene.enabled=false;fieldRows[scene.scene]=template.fields.map(item=>({key:item.key,source:subscriptionSourceForField(item.key)}));templatesOpened.value=false;notify('请核对字段来源后再启用场景')}
/** 隐藏或换号清空管理草稿和记录，旧异步操作不能恢复页面。 */
function clear(){readVersion++;operation++;deliveryVersion++;templateVersion++;authorized.value=false;settings.value=null;deliveries.value=[];total.value=0;loading.value=false;busy.value=false;error.value='';deliveryError.value='';templatesOpened.value=false;templatesLoading.value=false;templates.value=[];templateError.value='';for(const key of Object.keys(fieldRows))delete fieldRows[key as SubscriptionScene]}
watch([()=>state.user?.id,()=>state.user?.role,sessionRevision],()=>{clear();if(visible)void load()},{flush:'sync'})
onShow(()=>{visible=true;void load().then(()=>{if(tab.value==='deliveries'&&authorized.value)void loadDeliveries()})});onHide(()=>{visible=false;clear()});onUnload(()=>{disposed=true;visible=false;clear()})
</script>
<style scoped>
.subscriptions-admin-error{display:flex;flex-direction:column;gap:15.3846rpx}.subscriptions-admin-tabs{display:flex;gap:46.1538rpx;border-bottom:1px solid var(--line-subtle);margin-bottom:30.7692rpx}.subscriptions-admin-tab{display:flex;align-items:center;justify-content:center;min-height:92.3077rpx;padding:0 7.6923rpx;color:var(--muted);font-size:28.8462rpx;background:transparent;border-radius:0;border-bottom:3.8462rpx solid transparent}.subscriptions-admin-tab.active{color:var(--accent);border-bottom-color:var(--accent)}.subscriptions-master{display:flex;align-items:center;gap:23.0769rpx;background:var(--surface);padding:30.7692rpx;border-radius:19.2308rpx;margin-bottom:23.0769rpx;min-width:0}.subscriptions-setting-copy{flex:1;min-width:0}.subscriptions-setting-title{display:block;font-size:30.7692rpx;line-height:46.1538rpx;font-weight:600;overflow-wrap:anywhere}.subscriptions-setting-state{margin-left:auto;color:var(--muted);font-size:23.0769rpx;line-height:38.4615rpx;flex-shrink:0}.subscriptions-scene{border-bottom:1px solid var(--line-subtle)}.subscriptions-scene-heading{display:flex;align-items:center;gap:15.3846rpx;min-width:0;width:100%;text-align:left;min-height:107.6923rpx;background:transparent;padding:15.3846rpx 0;color:var(--muted)}.subscriptions-scene-body{padding:0 0 30.7692rpx;min-width:0}.subscriptions-inline{display:flex;align-items:center;justify-content:space-between;gap:15.3846rpx;min-width:0}.subscriptions-select-template{font-size:23.0769rpx;flex-shrink:0}.subscriptions-template-id{display:block;width:100%;box-sizing:border-box;font-size:25rpx}.subscriptions-field-heading{display:block;margin:30.7692rpx 0 15.3846rpx}.subscriptions-mapping{display:flex;gap:11.5385rpx;align-items:center;min-width:0;margin-top:15.3846rpx}.subscriptions-field-key{display:block;flex:1;min-width:0;width:0;font-size:25rpx;box-sizing:border-box}.subscriptions-source-picker{flex:1.2;min-width:0}.subscriptions-source-value{display:flex;align-items:center;justify-content:space-between;gap:7.6923rpx;font-size:23.0769rpx;padding:0 15.3846rpx;min-width:0}.subscriptions-remove{display:flex;align-items:center;justify-content:center;flex-shrink:0;width:61.5385rpx;height:84.6154rpx;padding:0;background:transparent;color:var(--muted)}.subscriptions-add-field{display:flex;align-items:center;justify-content:center;gap:11.5385rpx;width:100%;min-height:84.6154rpx;margin-top:15.3846rpx;font-size:25rpx}.subscriptions-admin-note{display:block;margin:30.7692rpx 0;overflow-wrap:anywhere}.subscriptions-save{width:100%;margin-top:30.7692rpx}.subscriptions-delivery-tools{display:flex;justify-content:space-between;align-items:center;gap:15.3846rpx;min-width:0}.subscriptions-delivery{padding:30.7692rpx 0;border-bottom:1px solid var(--line-subtle);min-width:0}.subscriptions-delivery-title{flex:1;min-width:0;font-size:28.8462rpx;line-height:46.1538rpx;overflow-wrap:anywhere}.subscriptions-delivery-status{color:var(--muted);font-size:23.0769rpx;line-height:38.4615rpx;max-width:42%;overflow-wrap:anywhere}.subscriptions-sent{color:var(--accent)}.subscriptions-delivery-error,.subscriptions-delivery-reason{display:block;color:#e4a18d;font-size:23.0769rpx;line-height:38.4615rpx;margin:15.3846rpx 0;overflow-wrap:anywhere}.subscriptions-retry{display:flex;margin-left:auto;font-size:25rpx}.subscriptions-more{display:flex;margin:23.0769rpx auto;font-size:25rpx}.subscriptions-template-option{display:flex;flex-direction:column;gap:7.6923rpx;width:100%;padding:23.0769rpx 0;text-align:left;color:var(--text);background:transparent;border-radius:0;border-bottom:1px solid var(--line-subtle);min-width:0}.subscriptions-template-code{display:block;font-size:19.2308rpx;line-height:34.6154rpx;color:var(--muted);overflow-wrap:anywhere}
</style>
